import{_ as a,c as t,o as r,ag as o}from"./chunks/framework.DRADY2L-.js";const m=JSON.parse('{"title":"Legacy Apple Calendar MCP Server","description":"","frontmatter":{},"headers":[],"relativePath":"mcp_servers/deprecated/apple-calendar/index.md","filePath":"mcp_servers/deprecated/apple-calendar/index.md"}'),d={name:"mcp_servers/deprecated/apple-calendar/index.md"};function n(l,e,i,c,s,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="legacy-apple-calendar-mcp-server" tabindex="-1">Legacy Apple Calendar MCP Server <a class="header-anchor" href="#legacy-apple-calendar-mcp-server" aria-label="Permalink to &quot;Legacy Apple Calendar MCP Server&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Original Python-based MCP server that interacted with iCloud calendars directly via the <code>caldav</code> library. It has been superseded by the Node.js implementation in <code>mcp_servers/calendarTool</code>, but remains here for historical reference.</p><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><ul><li><strong><code>main.py</code></strong> – registers five MCP tools covering CRUD operations on calendar events and calendar listing.</li><li><strong><code>apple_calendar.py</code></strong> – CalDAV helper that authenticates against <code>https://caldav.icloud.com</code>, enumerates calendars, and performs event operations.</li><li><strong><code>Dockerfile</code></strong> – Python 3.13 build (retained in this folder) capable of running the legacy service.</li></ul><h2 id="exposed-mcp-tools" tabindex="-1">Exposed MCP tools <a class="header-anchor" href="#exposed-mcp-tools" aria-label="Permalink to &quot;Exposed MCP tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>get_apple_calendar_events</code></td><td>Fetch events for a calendar between two dates (strings <code>YYYY-MM-DD</code>).</td></tr><tr><td><code>add_event_to_calendar</code></td><td>Create an all-day event given start/end timestamps.</td></tr><tr><td><code>update_event_in_calendar</code></td><td>Update an existing event by UID.</td></tr><tr><td><code>delete_event_from_calendar</code></td><td>Remove an event by UID.</td></tr><tr><td><code>list_all_calendars</code></td><td>Enumerate accessible calendars for the authenticated account.</td></tr></tbody></table><p>All tools rely on iCloud credentials (<code>APPLE_ID</code>, <code>APPLE_PASSWORD</code>) available as environment variables.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>Uses synchronous CalDAV calls without persistent storage or embeddings.</li><li>Does not support recurring event expansion beyond the limited logic in <code>map_events</code>.</li><li>No corresponding <code>*.mcp.yml</code>; the service must be invoked manually if ever needed.</li></ul><p>Prefer the maintained server in <code>mcp_servers/calendarTool</code> for production use.</p>',11)])])}const v=a(d,[["render",n]]);export{m as __pageData,v as default};
